import { Box, Flex, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import { Icon } from "../../../Icon";
import { SquareCheck } from "../../../Icon/icons";
import {
  type ConversationEvent,
  type ConversationEventAction,
  ConversationEventType,
} from "../../../types";
import { isHiddenSystemMemoryEntry } from "../../../utils";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";

// The chat row is a one-line summary — the full value lives in the
// "Memory set" details panel, so long values are cut hard here.
const MAX_VALUE_PREVIEW_LENGTH = 60;

const DISCOVERED_ENTRY_NAME = "__discovered__";

function formatMemoryValue(value: unknown, maxLength = MAX_VALUE_PREVIEW_LENGTH): string {
  const text = typeof value === "string" ? value : JSON.stringify(value);
  if (text === undefined) return "";
  return text.length > maxLength ? `${text.slice(0, maxLength - 1)}…` : text;
}

interface DiscoveredFact {
  key: string;
  value: unknown;
}

// The scratchpad write carries the whole cumulative fact list (not the delta),
// engine-ordered oldest-first with oldest-first eviction — so the last entry is
// the newest discovery. A single write can append more than one fact, and the
// event does not tell us how many it added, so the summary surfaces the newest
// fact and, when the list holds more, a "+N more" count rather than pretending
// there is only one.
function parseDiscoveredFacts(value: unknown): DiscoveredFact[] {
  if (!Array.isArray(value)) return [];
  const facts: DiscoveredFact[] = [];
  for (const item of value) {
    if (typeof item !== "object" || item === null) continue;
    const { key, value: factValue } = item as Record<string, unknown>;
    if (typeof key === "string") facts.push({ key, value: factValue });
  }
  return facts;
}

function generateMemoryWriteMessage(event: ConversationEvent) {
  const isCleared =
    event.conversationEventType === ConversationEventType.MemoryCleared || event.value == null;

  const modifiedSuffix = event.metadata?.was_modified_by_studio ? " (modified)" : "";

  // Memory entries are scoped ("card_replace.replacement_reason"); the chat
  // shows the bare entry name, matching the memory pane rows.
  const entryName = event.name?.split(".").pop() ?? event.name;

  const memoryValue = event.value;

  if (entryName === DISCOVERED_ENTRY_NAME) {
    const facts = parseDiscoveredFacts(memoryValue);
    const newest = facts.at(-1);
    const extraCount = facts.length - 1;
    return (
      <Text textStyle="xs" lineClamp={1} wordBreak="break-all">
        <Text as="span" fontWeight="medium">
          {newest?.key ?? "fact"}
        </Text>{" "}
        discovered
        {newest && newest.value !== undefined ? (
          <>
            {" · "}
            <Text as="span" fontWeight="medium">
              {formatMemoryValue(newest.value, 40)}
            </Text>
          </>
        ) : null}
        {extraCount > 0 ? ` (+${extraCount} more)` : null}
      </Text>
    );
  }

  return (
    <Text textStyle="xs" lineClamp={1} wordBreak="break-all">
      <Text as="span" fontWeight="medium">
        {entryName}
      </Text>{" "}
      {isCleared ? "cleared" : "set to"}
      {isCleared ? null : (
        <>
          {" "}
          <Text as="span" fontWeight="medium">
            {formatMemoryValue(memoryValue)}
          </Text>
        </>
      )}
      {modifiedSuffix}
    </Text>
  );
}

interface MemoryWriteEventProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
}

export const MemoryWriteEvent = forwardRef<HTMLDivElement | null, MemoryWriteEventProps>(
  (props: MemoryWriteEventProps, ref) => {
    const { event, isSelected = false, conversationEventActions, ...otherProps } = props;
    const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
    const [isHovered, setIsHovered] = React.useState(false);

    // Engine housekeeping writes (silence timeouts, session metadata, …) are
    // noise in the chat. The same predicate decides whether a write counts
    // toward its tool call's caret, so a hidden write never leaves an empty one.
    if (isHiddenSystemMemoryEntry(event.name || "")) {
      return null;
    }

    return (
      <Flex
        css={hoverableContainerSx}
        ref={ref}
        tabIndex={0}
        position="relative"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        {...otherProps}
      >
        {isHovered && (
          <ConversationEventActionButton event={event} actions={conversationEventActions} />
        )}
        <Box css={baseMessageSx}>
          <Icon icon={SquareCheck} style={iconSx} />
          {generateMemoryWriteMessage(event)}
        </Box>
      </Flex>
    );
  },
);
